diff --git a/repro/check.ts b/repro/check.ts
new file mode 100644
index 000000000..b786742b6
--- /dev/null
+++ b/repro/check.ts
@@ -0,0 +1,29 @@
+type Wrapper<T> = {
+    _type: T
+}
+
+function stringWrapper(): Wrapper<string> {
+    return { _type: "" }
+}
+
+function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T> {
+    return { _type: obj }
+}
+
+const value = objWrapper({
+    prop1: stringWrapper() as Wrapper<"hello">
+})
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>> 
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> } 
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+
+declare const t: Test;
+
+// Expected: Test is { prop1: "hello"; }, so this assignment should compile.
+const expected: { prop1: "hello" } = t;
+
+// Prints the resolved type in the error message.
+const actual: never = t;
diff --git a/repro/semantic.ts b/repro/semantic.ts
new file mode 100644
index 000000000..1ebb401b4
--- /dev/null
+++ b/repro/semantic.ts
@@ -0,0 +1,17 @@
+type Wrapper<T> = { _type: T }
+declare function stringWrapper(): Wrapper<string>;
+declare function objWrapper<T extends Record<string, Wrapper<any>>>(obj: T): Wrapper<T>;
+
+const value = objWrapper({ prop1: stringWrapper() as Wrapper<"hello"> })
+
+type Unwrap<T extends Wrapper<any>> = T['_type'] extends Record<string, Wrapper<any>>
+    ? { [Key in keyof T['_type']]: Unwrap<T['_type'][Key]> }
+    : T['_type']
+
+type Test = Unwrap<typeof value>
+declare const t: Test;
+
+const a: "hello" = t.prop1;                 // ok if prop1 is "hello"
+const b: Wrapper<"hello"> = t.prop1;        // errors if prop1 is "hello"
+const c: { prop1: Wrapper<"hello"> } = t;   // errors if Test is { prop1: "hello" }
+const d: { prop1: "hello" } = t;            // ok if Test is { prop1: "hello" }
diff --git a/repro/separate_line.ts b/repro/separate_line.ts
